<div class="quiz-wrapper quiz-taking-page"><div class="quiz-header page-header"><div class="page-header-info"><h1>Quiz</h1><p><?=count($quiz['questions'])?> question(s) · Take your time and choose the best answer.</p></div></div><form method="post" action="<?=url('student/quiz-submit.php')?>"><?=CSRF::field()?><input type="hidden" name="quiz_id" value="<?= (int)$quiz['id']?>">
<?php foreach($quiz['questions'] as $i=>$q):$data=json_decode($q['answer_data']??'',true)?:[];?><div class="card quiz-question-card"><div class="quiz-question-meta"><span class="question-number">Question <?= $i+1 ?></span><span class="badge"><?=strtoupper(e($q['type']))?></span></div><p class="quiz-question-text"><?=e($q['question_text'])?></p>
<?php if($q['type']==='mcq'):foreach(($data['options']??[]) as $opt):?><label class="quiz-option-label"><input type="radio" name="answers[<?= (int)$q['quiz_question_id']?>]" value="<?=e($opt)?>"> <?=e($opt)?></label><?php endforeach;?>
<?php elseif($q['type']==='match'):foreach(($data['left_items']??[]) as $left):?><div class="quiz-match-row"><label><?=e($left)?> <select name="answers[<?= (int)$q['quiz_question_id']?>][<?=e($left)?>]"><option value="">Select an answer</option><?php foreach(($data['right_items']??[]) as $right):?><option value="<?=e($right)?>"><?=e($right)?></option><?php endforeach;?></select></label></div><?php endforeach;?>
<?php else:?><textarea class="form-control" rows="4" name="answers[<?= (int)$q['quiz_question_id']?>]"></textarea><?php endif;?></div><?php endforeach;?>
<div class="quiz-actions"><button class="btn btn-primary">Submit Quiz</button></form><form method="post" action="<?=url('student/quiz-discard.php')?>" onsubmit="return confirm('Discard this quiz? All current answers will be lost.');"><?=CSRF::field()?><input type="hidden" name="quiz_id" value="<?= (int)$quiz['id']?>"><button class="btn btn-secondary">Discard Quiz</button></form></div></div>
